export function deriveModelDisplayName(modelId) {
    const m = modelId.match(/^claude-([a-z]+)-(\d+)-(\d+)(?:-\d+)?$/i);
    if (!m)
        return modelId;
    const [, family, major, minor] = m;
    const capitalized = family.charAt(0).toUpperCase() + family.slice(1).toLowerCase();
